package com.johnny.hotel.repair;import org.apache.ibatis.annotations.*;import java.math.*;import java.time.*;import java.util.*;
@Mapper public interface RepairOrderMapper{
 @Insert("INSERT INTO room_repair_task(task_id,inspection_id,room_id,issue_description,priority,status,estimated_cost) VALUES(#{taskId},#{inspectionId},#{roomId},#{issueDescription},#{priority},0,#{estimatedCost})")@Options(useGeneratedKeys=true,keyProperty="id")int insert(RepairOrder r);
 @Select("SELECT * FROM room_repair_task WHERE id=#{id}")RepairOrder find(Long id);@Select("SELECT * FROM room_repair_task WHERE id=#{id} FOR UPDATE")RepairOrder lock(Long id);@Select("SELECT * FROM room_repair_task WHERE inspection_id=#{id} FOR UPDATE")RepairOrder byInspection(Long id);@Select("SELECT * FROM room_repair_task WHERE task_id=#{id} FOR UPDATE")RepairOrder byTask(Long id);
 @Update("UPDATE room_repair_task SET status=1,started_time=COALESCE(started_time,#{now}) WHERE task_id=#{task} AND status=0")int start(@Param("task")Long task,@Param("now")LocalDateTime now);
 @Update("UPDATE room_repair_task SET status=2,actual_cost=#{cost},notes=#{notes},completed_by=#{actor},completed_time=#{now} WHERE id=#{id} AND status IN(0,1)")int complete(@Param("id")Long id,@Param("cost")BigDecimal cost,@Param("notes")String notes,@Param("actor")Long actor,@Param("now")LocalDateTime now);
 @Update("UPDATE room_repair_task SET status=3,notes=#{notes},completed_by=#{actor},completed_time=#{now} WHERE id=#{id} AND status IN(0,1)")int cancel(@Param("id")Long id,@Param("notes")String notes,@Param("actor")Long actor,@Param("now")LocalDateTime now);
 @Select("<script>SELECT * FROM room_repair_task <where><if test='room!=null'>room_id=#{room}</if><if test='status!=null'> AND status=#{status}</if><if test='inspection!=null'> AND inspection_id=#{inspection}</if></where> ORDER BY create_time DESC,id DESC LIMIT #{offset},#{size}</script>")List<RepairOrder> page(@Param("room")Long room,@Param("status")Integer status,@Param("inspection")Long inspection,@Param("offset")int offset,@Param("size")int size);
 @Select("<script>SELECT COUNT(*) FROM room_repair_task <where><if test='room!=null'>room_id=#{room}</if><if test='status!=null'> AND status=#{status}</if><if test='inspection!=null'> AND inspection_id=#{inspection}</if></where></script>")long count(@Param("room")Long room,@Param("status")Integer status,@Param("inspection")Long inspection);
}
